/**
 * Panel CRM jako aplikacja na telefonie (ikona na ekranie glownym, okno bez paska przegladarki).
 * Manifest i ikony sa publiczne: przegladarka pobiera je bez hasla (inaczej instalacja sie nie uda).
 * Nie zawieraja zadnych danych. Ikony: sygnet skaluj.ai na bialym tle, PNG zakodowane w base64.
 */
const ICONS = {
  "/ikona-512.png": "",
  "/ikona-192.png": "",
  "/apple-touch-icon.png": "",
};

/* Ekrany startowe iPhone'a: bez nich iOS przy uruchamianiu pokazuje pusty (w trybie ciemnym czarny) ekran.
   iOS bierze obraz tylko wtedy, gdy rozmiar pasuje co do piksela, dlatego jest osobny plik na kazdy rozmiar ekranu. */
const SPLASH = {
  "/splash-640x1136.png": { media: "(device-width: 320px) and (device-height: 568px) and (-webkit-device-pixel-ratio: 2) and (orientation: portrait)", png: "" },
  "/splash-750x1334.png": { media: "(device-width: 375px) and (device-height: 667px) and (-webkit-device-pixel-ratio: 2) and (orientation: portrait)", png: "" },
  "/splash-1242x2208.png": { media: "(device-width: 414px) and (device-height: 736px) and (-webkit-device-pixel-ratio: 3) and (orientation: portrait)", png: "" },
  "/splash-1125x2436.png": { media: "(device-width: 375px) and (device-height: 812px) and (-webkit-device-pixel-ratio: 3) and (orientation: portrait)", png: "" },
  "/splash-828x1792.png": { media: "(device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio: 2) and (orientation: portrait)", png: "" },
  "/splash-1242x2688.png": { media: "(device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio: 3) and (orientation: portrait)", png: "" },
  "/splash-1170x2532.png": { media: "(device-width: 390px) and (device-height: 844px) and (-webkit-device-pixel-ratio: 3) and (orientation: portrait)", png: "" },
  "/splash-1284x2778.png": { media: "(device-width: 428px) and (device-height: 926px) and (-webkit-device-pixel-ratio: 3) and (orientation: portrait)", png: "" },
  "/splash-1179x2556.png": { media: "(device-width: 393px) and (device-height: 852px) and (-webkit-device-pixel-ratio: 3) and (orientation: portrait)", png: "" },
  "/splash-1290x2796.png": { media: "(device-width: 430px) and (device-height: 932px) and (-webkit-device-pixel-ratio: 3) and (orientation: portrait)", png: "" },
  "/splash-1206x2622.png": { media: "(device-width: 402px) and (device-height: 874px) and (-webkit-device-pixel-ratio: 3) and (orientation: portrait)", png: "" },
  "/splash-1320x2868.png": { media: "(device-width: 440px) and (device-height: 956px) and (-webkit-device-pixel-ratio: 3) and (orientation: portrait)", png: "" },
  "/splash-1260x2736.png": { media: "(device-width: 420px) and (device-height: 912px) and (-webkit-device-pixel-ratio: 3) and (orientation: portrait)", png: "" },
};

/** Znaczniki <link> do <head>: ekrany startowe dla iPhone'a. */
export const startupLinks = Object.entries(SPLASH)
  .map(([href, s]) => `<link rel="apple-touch-startup-image" media="${s.media}" href="${href}">`)
  .join("");

const MANIFEST = JSON.stringify({
  name: "CRM skaluj.ai",
  short_name: "CRM",
  description: "Zgłoszenia i statystyki skaluj.ai",
  lang: "pl",
  start_url: "/",
  scope: "/",
  display: "standalone",
  orientation: "portrait",
  background_color: "#ffffff",
  theme_color: "#ffffff",
  icons: [
    { src: "/ikona-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
    { src: "/ikona-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
    { src: "/ikona-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
  ],
});

const pub = (type) => ({
  "Content-Type": type,
  "Cache-Control": "public, max-age=86400",
  "X-Content-Type-Options": "nosniff",
  "X-Robots-Tag": "noindex, nofollow",
});

/** Zwraca odpowiedz dla manifestu albo ikony, a dla innych sciezek null. */
export function appAsset(path) {
  if (path === "/manifest.webmanifest") return new Response(MANIFEST, { headers: pub("application/manifest+json; charset=UTF-8") });
  const icon = ICONS[path] || SPLASH[path]?.png;
  if (!icon) return null;
  return new Response(Uint8Array.from(atob(icon), (c) => c.charCodeAt(0)), { headers: pub("image/png") });
}
